/* Ticket UI uses shared role, catalogue, media, attention and drawer foundations. */
const names112={metadata:'Perubahan Metadata',audio:'Penggantian Audio',cover:'Penggantian Cover',takedown:'Penurunan Rilisan',cid:'Ajukan Content ID','release-claim':'Lepaskan Klaim Video','disable-cid':'Nonaktifkan Content ID',availability:'Masalah Ketersediaan Rilisan'};
const states112={submitted:'Diajukan',handling:'Dalam Penanganan',label:'Perlu Tanggapan Label',distributor:'Menunggu Distributor',done:'Selesai'};
const events112={created:'Permintaan diajukan',claim:'Penanganan dimulai',assign:'Penanganan dialihkan',request:'Kelengkapan diminta',complete:'Kelengkapan dikirim',send:'Diteruskan ke distributor',followup:'Tindak lanjut dicatat',results:'Hasil pemeriksaan dicatat',finish:'Tiket diselesaikan',internal:'Catatan internal',escalate:'Kasus dieskalasikan','clear-escalation':'Peninjauan dicatat','report-again':'Masalah dilaporkan kembali',reopen:'Kasus dibuka kembali','link-new':'Tiket terkait ditautkan',message:'Pesan ditambahkan',extend:'Dampak tambahan dilaporkan'};
const fieldNames112={title:'Judul',genre:'Genre',subgenre:'Subgenre',year:'Tahun',copyright:'© Pemilik karya',master:'℗ Pemilik rekaman',primary:'Artis utama',featured:'Artis tambahan',language:'Bahasa lagu',lyricLanguage:'Bahasa lirik',lyrics:'Lirik',composer:'Komposer',lyricist:'Penulis lirik',arranger:'Arranger',producer:'Produser',explicit:'Konten eksplisit'};
const ui112={tab:'all',q:'',status:'all',category:'all',draft:null,open:null};let payload112=null,docEditor112=null;
const B112=(text,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-t112="${action}" data-id="${E(id)}">${text}</button>`;
const required112='<i class="required105" aria-label="wajib">*</i>';
function allowed112(){return isLabel10()||ten.role==='super'||!!allowedModule(modules.find(m=>m.id==='tickets'))}
function write112(){return allowed112()&&(isLabel10()||ten.role==='super'||permission('support')==='direct'&&!['read','blocked'].includes(access8('tickets')))}
function actor112(){return {...actor11(),write:write112(),active:!!(member10().active&&member10().contract&&!member10().blocked105)}}
function rows112(){if(!allowed112())return [];return Tickets112.init(ten).tickets.filter(t=>Tickets112.visible(actor112(),t))}
function releaseChoices112(){return ten.releases.filter(r=>scope11().includes(r.member)&&['delivered','followup','partial','partial_closed','live','taken_down'].includes(r.status))}
function ticket112(id){return rows112().find(t=>t.id===id)}
function run112(action,p){if(!write112())throw Error('Akses tindakan tidak tersedia.');const before=structuredClone(ten);try{if(action==='assign'&&!people.some(x=>x.id===p.handler&&(x.super||data.roles.find(r=>r.id===data.assignments[x.id])?.rules.support==='direct')))throw Error('Pilih petugas dengan akses penanganan tiket.');const id=Tickets112.act(ten,actor112(),action,p,calendar11());save10();return id}catch(err){Object.keys(ten).forEach(k=>delete ten[k]);Object.assign(ten,before);throw err}}
function route112(){closeModal();document.querySelector('#ticket-drawer112')?.close();module102('tickets');render()}
function tag112(t){return statusBadge111(states112[t.status],t.status==='done'?'green':t.status==='label'?'mustard':t.status==='submitted'?'neutral':'blue')}
function value112(v){return Array.isArray(v)?v.map(x=>typeof x==='object'?x.name:String(x)).join(', ')||'—':typeof v==='boolean'?v?'Ya':'Tidak':String(v??'')||'—'}
function person112(id){return people.find(p=>p.id===id)?.name||RM10.getMember(ten,id)?.name||id||'Belum ditangani'}
function row112(t){const a=Tickets112.attention(ten,t,actor112()),finished=t.items.filter(i=>i.status==='confirmed').length;return `<article class="ticket-row112"><div class="ticket-object112">${t.source.cover?.url?`<img src="${E(t.source.cover.url)}" alt="">`:'<span class="ticket-art112">♫</span>'}<div><small>${E(t.id)} · ${E(names112[t.category])}</small><strong>${E(t.source.title)}</strong><small>${E(RM10.getMember(ten,t.member)?.name||'')} · ${E(t.source.artist)}</small></div></div><div>${tag112(t)}${a?`<small class="ticket-due112">${E(a.text)}</small>`:''}<small>${finished} / ${t.items.length} bagian terkonfirmasi</small></div><div class="ticket-owner112"><strong>${E(person112(t.handler))}</strong><small>${date10(t.updated,true)} WIB</small>${t.escalated?statusBadge111('Perlu peninjauan','mustard'):''}</div>${B112('↗','detail',t.id,'arrow107')}</article>`}
function attention112(rows=rows112()){const needs=rows.map(t=>({t,a:Tickets112.attention(ten,t,actor112())})).filter(x=>x.a&&(isLabel10()||ten.role==='super'||!x.t.handler||x.t.handler===state.user));if(!needs.length)return '';const x=needs[0],tone=x.a.tone;return `<section class="attention9 ${tone==='urgent'?'red9':tone==='info'?'blue':''}"><h3>${E(x.a.text)} · ${needs.length}</h3><p>${E(x.t.source.title)}${needs.length>1?' dan '+(needs.length-1)+' tiket lainnya.':'.'}</p>${B112('Tinjau','detail',x.t.id)}</section>`}
function page112(){if(!allowed112())return denied9();const tabs=isLabel10()?[['all','Tiket Saya'],['response','Perlu Tanggapan'],['done','Selesai'],['draft','Draft']]:[['all','Semua Tiket'],['queue','Antrean'],['mine','Penanganan Saya'],['label','Menunggu Label'],['distributor','Menunggu Distributor'],['done','Selesai'],...(ten.role==='super'?[['monitor','Pemantauan']]:[])];if(!tabs.some(x=>x[0]===ui112.tab))ui112.tab='all';let list=rows112().filter(t=>(ui112.tab==='all'||ui112.tab==='queue'&&t.status==='submitted'||ui112.tab==='mine'&&t.handler===state.user&&t.status!=='done'||ui112.tab==='response'&&t.status==='label'||ui112.tab==='label'&&t.status==='label'||ui112.tab==='distributor'&&t.status==='distributor'||ui112.tab==='done'&&t.status==='done'||ui112.tab==='monitor'&&(t.escalated||t.reopenRequest||Tickets112.attention(ten,t,actor112())))&&(ui112.status==='all'||ui112.status===t.status)&&(ui112.category==='all'||ui112.category===t.category)&&(t.id+' '+t.source.title+' '+person112(t.member)).toLowerCase().includes(ui112.q.toLowerCase())).sort((a,b)=>b.updated-a.updated);return `<div class="page112"><div class="pagehead"><div><span class="eyebrow107">TIKET BANTUAN</span><h1>${isLabel10()?'Setiap permintaan, satu riwayat.':'Permintaan & tindak lanjut.'}</h1><p>${isLabel10()?'Ajukan perubahan, lengkapi informasi, dan lihat hasil untuk rilisanmu.':'Penanggung jawab jelas. Perubahan dan hasil tetap dapat ditelusuri.'}</p></div>${isLabel10()?B112('Ajukan permintaan','new','','primary'):B112('Panduan penanganan','guide','','text')}</div><div class="tabs" data-switch-key105="tickets112">${tabs.map(([id,text])=>B112(text,'tab',id,ui112.tab===id?'active':'')).join('')}</div>${ui112.tab==='draft'?drafts112():`<div class="tools111 ticket-tools112"><input type="search" id="ticket-search112" value="${E(ui112.q)}" placeholder="Cari rilisan, label, atau nomor tiket" aria-label="Cari tiket"><label>Jenis <select id="ticket-category112"><option value="all">Semua permintaan</option>${Object.entries(names112).map(([id,text])=>`<option value="${id}" ${ui112.category===id?'selected':''}>${text}</option>`).join('')}</select></label><label>Status <select id="ticket-status112"><option value="all">Semua status</option>${Object.entries(states112).map(([id,text])=>`<option value="${id}" ${ui112.status===id?'selected':''}>${text}</option>`).join('')}</select></label></div>${attention112(list)}<section class="panel111 ticket-list112">${list.map(row112).join('')||`<div class="empty11"><span>✦</span><h2>Belum ada tiket pada daftar ini.</h2><p>${isLabel10()?'Permintaan dapat dibuat dari sini atau dari detail rilisan.':'Tiket mengikuti akses dan filter yang kamu pilih.'}</p>${isLabel10()?B112('Ajukan permintaan','new','','primary'):''}</div>`}</section>`}</div>`}
function drafts112(){return `<section class="panel111">${Tickets112.init(ten).drafts.filter(d=>d.account===ten.member).map(d=>`<div class="action-row"><div class="grow"><strong>${E(names112[d.payload.category])} · ${E(d.payload.source?.title||'Belum memilih rilisan')}</strong><small>Disimpan ${date10(d.at,true)} WIB · belum dikirim</small></div>${B112('Lanjutkan','draft',d.id)}</div>`).join('')||'<p>Belum ada draft permintaan.</p>'}</section>`}
function fresh112(release='',category='metadata'){const r=releaseChoices112().find(r=>r.id===release)||releaseChoices112()[0];return {category,release:r?.id||'',source:r?Tickets112.catalogue(r):null,note:'',reason:'',tracks:r?.songs?.map(t=>t.id)||[],changes:[],platforms:[],condition:'missing',urls:[''],creators:[],consent:false,checked:false,files:[],audio:null,cover:null,preview:0}}
function new112(release='',category='metadata',draft=null){if(!isLabel10())return;payload112=draft?structuredClone(draft.payload):fresh112(release,category);if(draft)payload112.draftId=draft.id;ui112.draft=payload112.draftId||null;openForm112()}
function textField112(name,label,value='',extra=''){return `<label>${label}<input name="${name}" value="${E(value)}" ${extra}></label>`}
function trackPicker112(multiple=true){const d=payload112;return `<fieldset class="track-select112"><legend>${multiple?'Lagu terkait':'Lagu yang diganti'} ${required112}</legend>${(d.source?.songs||[]).map(t=>`<label class="check11"><input type="${multiple?'checkbox':'radio'}" name="track112" value="${E(t.id)}" ${d.tracks.includes(t.id)?'checked':''}><span><strong>${E(t.number+'. '+t.title)}</strong><small>ISRC ${E(t.isrc||'belum tersedia')}</small></span></label>`).join('')}</fieldset>`}
function metadataFields112(){const d=payload112,section=(scope,values,track='',title='Data rilisan')=>`<details class="metadata-section112" open><summary>${E(title)}</summary><div class="formgrid11">${Tickets112.fields[scope].map(key=>{const ch=d.changes.find(c=>c.scope===scope&&c.track===track&&c.field===key),v=ch?ch.value:values[key];return `<label>${E(fieldNames112[key])}${key==='explicit'?`<select data-meta112="${scope}" data-track="${E(track)}" data-field="${key}"><option value="false" ${v===false?'selected':''}>Tidak</option><option value="true" ${v===true?'selected':''}>Ya</option></select>`:`<textarea rows="${key==='lyrics'?4:1}" data-meta112="${scope}" data-track="${E(track)}" data-field="${key}" data-array="${Array.isArray(v)}" data-object="${Array.isArray(v)&&v.some(x=>typeof x==='object')}" maxlength="${key==='lyrics'?10000:1500}">${E(Array.isArray(v)?v.map(x=>typeof x==='object'?x.name:x).join('\n'):v)}</textarea>${Array.isArray(v)?'<small>Satu nama per baris. Data lain dari artis yang sama tetap dipertahankan.</small>':''}`}</label>`}).join('')}</div></details>`;return section('release',d.source.release)+d.source.songs.map(t=>section('track',t.metadata,t.id,t.number+'. '+t.title)).join('')}
function creatorFields112(){const d=payload112;return `<p class="sample111">Data dan dokumen berikut mengikuti formulir repo. Ketentuan surat, pencipta luar negeri, dan kelayakan lagu masih perlu verifikasi staf.</p>${trackPicker112()}<div id="creators112">${d.creators.map((c,i)=>`<article class="creator112"><div class="spread"><h3>Pencipta ${i+1}</h3>${d.creators.length>1?B112('Hapus','remove-creator',String(i),'text'):''}</div><div class="formgrid11">${textField112('creator-name-'+i,'Nama sesuai KTP '+required112,c.name,'data-creator112="'+i+'" data-field="name" required')}${textField112('creator-nik-'+i,'NIK '+required112,c.nik,'data-creator112="'+i+'" data-field="nik" inputmode="numeric" pattern="[0-9]{16}" maxlength="16" required')}${textField112('creator-domicile-'+i,'Domisili '+required112,c.domicile,'data-creator112="'+i+'" data-field="domicile" required')}${textField112('creator-city-'+i,'Kota penandatanganan '+required112,c.city,'data-creator112="'+i+'" data-field="city" required')}</div><fieldset><legend>Lagu terkait</legend>${d.source.songs.filter(t=>d.tracks.includes(t.id)).map(t=>`<label class="check11"><input type="checkbox" data-creator-track112="${i}" value="${E(t.id)}" ${c.tracks.includes(t.id)?'checked':''}>${E(t.title)}</label>`).join('')}</fieldset><div class="document-pair112"><label class="upload-ticket112">${icon('user')}<strong>KTP pencipta ${required112}</strong><small>${E(c.ktp?.name||'JPG / PNG · orientasi dan batas disiapkan untuk ditinjau')}</small><input type="file" data-ticket-file112="ktp" data-creator="${i}" accept="image/jpeg,image/png,image/webp">${c.ktp?B112('Tinjau dokumen','creator-ktp',String(i),'text'):''}</label><label class="upload-ticket112"><span>✍</span><strong>Tanda tangan ${required112}</strong><small>${E(c.signature?.name||'JPG / PNG dengan tanda tangan yang jelas')}</small><input type="file" data-ticket-file112="signature" data-creator="${i}" accept="image/jpeg,image/png">${c.signature?`<img src="${E(c.signature.preview)}" alt="Pratinjau tanda tangan">`:''}</label></div></article>`).join('')}</div>${B112('+ Tambah pencipta','add-creator','','text')}${B112('Pratinjau pernyataan','statement','','text')}<label class="check11"><input type="checkbox" name="consent112" ${d.consent?'checked':''}>Saya menyatakan data benar dan memiliki persetujuan untuk penggunaan dokumen pencipta dalam pengajuan ini. ${required112}</label>`}
function categoryForm112(){const d=payload112;if(!d.source)return '<p>Belum ada rilisan yang dikirim atau tayang. Siapkan draft melalui menu Rilisan.</p>';if(d.category==='metadata')return metadataFields112()+`<section class="change-summary112"><h3>Ringkasan perubahan</h3><div id="metadata-diff112">${diffHtml112(d)}</div></section>`;
if(d.category==='audio')return trackPicker112(false)+`<div class="upload-ticket112"><strong>WAV pengganti ${required112}</strong><p>44,1 / 48 kHz. Pilih lagu terlebih dahulu.</p><input type="file" data-ticket-file112="audio" accept=".wav,audio/wav">${d.audio?`<strong>${E(d.audio.name)}</strong><small>${d.audio.duration.toFixed(2)} detik · ${d.audio.sampleRate/1000} kHz</small><audio controls data-blob105="${E(d.audio.key)}"></audio><label>Mulai cuplikan (detik)<input type="number" name="preview112" min="0" max="${d.audio.duration-.01}" step=".01" value="${d.preview}"></label>`:''}</div>${d.tracks.length===1&&d.source.songs.find(t=>t.id===d.tracks[0])?.audio?.key?`<details><summary>Dengarkan audio sebelumnya</summary><audio controls data-blob105="${E(d.source.songs.find(t=>t.id===d.tracks[0]).audio.key)}"></audio></details>`:''}<p class="note107">Versi rekaman yang berbeda akan ditinjau petugas. Unggahan ini belum mengganti audio katalog.</p>`;
if(d.category==='cover')return `<div class="cover-pair112"><article><small>Cover saat ini</small>${d.source.cover?.url?`<img src="${E(d.source.cover.url)}" alt="Cover saat ini">`:'<div class="cover-empty112">Berkas sebelumnya belum tersedia</div>'}</article><article><small>Usulan cover baru</small>${d.cover?.url?`<img src="${E(d.cover.url)}" alt="Cover baru">`:'<div class="cover-empty112">JPG / PNG · 3000 × 3000</div>'}<input type="file" data-ticket-file112="cover" accept="image/jpeg,image/png">${d.cover?`<small>${E(d.cover.name)} · 3000 × 3000 px</small>`:''}</article></div><p>Artwork tidak dipotong atau diregangkan otomatis.</p>`;
if(d.category==='takedown')return `<div class="notice111"><strong>Seluruh rilisan</strong><p>${d.source.songs.length} lagu akan diajukan untuk penurunan. Katalog dan riwayat tetap tersimpan.</p></div><label>Alasan penurunan ${required112}<select name="reason112">${['','Revisi Metadata','Pindah Aggregator','Konflik Hak Cipta','Konflik Internal'].map(x=>`<option ${d.reason===x?'selected':''} value="${E(x)}">${x||'Pilih alasan'}</option>`).join('')}</select></label><p id="takedown-guidance112" ${d.reason==='Revisi Metadata'?'':'hidden'}>Jika hanya ingin memperbaiki informasi rilisan, gunakan Perubahan Metadata. Lanjutkan penurunan jika distribusinya memang perlu dihentikan.</p><label class="check11"><input type="checkbox" name="checked112" ${d.checked?'checked':''}>Saya mengajukan penurunan seluruh rilisan, termasuk semua lagu di dalamnya. ${required112}</label>`;
if(d.category==='cid')return creatorFields112();
if(d.category==='release-claim')return trackPicker112()+`<fieldset class="urls112"><legend>Video yang dimaksud ${required112}</legend>${d.urls.map((u,i)=>`<label>Video ${i+1}<input type="url" data-video112="${i}" value="${E(u)}" placeholder="https://www.youtube.com/watch?v=…" required></label>${d.urls.length>1?B112("Hapus video","remove-video",String(i),"text"):""}`).join('')}${B112('+ Tambah video','add-video','','text')}</fieldset><p>Permintaan menyasar klaim pada video ini. Petugas akan memastikan klaim berada dalam cakupan pengelolaan Rilis Musik/distributor.</p>`;
if(d.category==='disable-cid')return `<p class="sample111">Kemampuan penonaktifan dan perlakuan terhadap klaim sebelumnya masih perlu konfirmasi staf. Pengajuan ini masuk peninjauan petugas.</p>${trackPicker112()}<label class="check11"><input name="checked112" type="checkbox" ${d.checked?'checked':''}>Saya meminta penonaktifan Content ID untuk lagu terpilih. ${required112}</label><p>Ini bukan permintaan menurunkan rilisan dari platform atau melepas satu klaim video.</p>`;
return `<label>Tautan terkait (opsional)<input type="url" data-video112="0" value="${E(d.urls[0]||'')}" placeholder="https://…"><small>Tidak perlu tautan jika rilisan belum ditemukan.</small></label>${trackPicker112()}<fieldset><legend>Platform terdampak ${required112}</legend>${['Spotify','Apple Music','YouTube Music','TikTok','Deezer','Amazon Music','Platform lain','Belum yakin'].map(x=>`<label class="check11"><input type="checkbox" name="platform112" value="${x}" ${d.platforms.includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset><label>Kondisi ${required112}<select name="condition112"><option value="missing" ${d.condition==='missing'?'selected':''}>Belum tersedia</option><option value="disappeared" ${d.condition==='disappeared'?'selected':''}>Sebelumnya tersedia, sekarang tidak ditemukan</option></select></label>${ten.releases.find(r=>r.id===d.release)?.date?`<p class="note107">Dijadwalkan pada ${date10(ten.releases.find(r=>r.id===d.release).date)}. ${Date.parse(ten.releases.find(r=>r.id===d.release).date+'T00:00:00+07:00')>ten.now?'Jika hanya menanyakan jadwal, periksa perkembangan distribusi di detail rilisan.':'Tim akan memeriksa status pengiriman dan ketersediaan platform.'}</p>`:''}`}
function diffHtml112(d){if(!d.source)return '';let diffs=[];try{diffs=Tickets112.diffs(d.source,d)}catch{}return diffs.map(i=>`<div class="diff-row112"><strong>${E(i.label)}</strong><div><small>Sebelumnya</small><p>${E(value112(i.before))}</p></div><div><small>Usulan</small><p>${E(value112(i.after))}</p></div></div>`).join('')||'<p>Ubah isian yang diperlukan. Hanya perbedaan yang akan diajukan.</p>'}
function openForm112(){const d=payload112;if(!d)return;document.querySelector('#ticket-drawer112')?.close();reviewDialogUI(d.extension?'Tambahkan dampak pada tiket '+d.extension:d.draftId?'Lanjutkan draft permintaan':'Ajukan permintaan',`<form data-form112="create" class="form111 ticket-form112"><div class="formgrid11"><label>Jenis permintaan ${required112}<select name="category112" ${d.extension?"disabled":""}>${Object.entries(names112).map(([id,text])=>`<option value="${id}" ${d.category===id?'selected':''}>${text}</option>`).join('')}</select></label><label>Rilisan ${required112}<select name="release112" ${d.extension?"disabled":""}><option value="">Pilih rilisan</option>${releaseChoices112().map(r=>`<option value="${E(r.id)}" ${d.release===r.id?'selected':''}>${E(r.title)}</option>`).join('')}</select></label></div>${d.source?`<div class="ticket-id112"><strong>${E(d.source.title)}</strong><small>UPC ${E(d.source.upc||'belum tersedia')}</small><details><summary>${d.source.songs.length} lagu · lihat ISRC</summary>${d.source.songs.map(t=>`<p>${E(t.title)} · ${E(t.isrc||'ISRC belum tersedia')}</p>`).join('')}</details></div>`:''}${d.source&&JSON.stringify(d.source)!==JSON.stringify(Tickets112.catalogue(ten.releases.find(r=>r.id===d.release)))?`<div class="notice111"><strong>Data katalog telah diperbarui.</strong><p>Muat data terbaru, lalu periksa kembali perbandingan dan cakupan sebelum mengirim.</p>${B112("Muat data terbaru","refresh-source","","text")}</div>`:""}${categoryForm112()}<label>${d.category==='metadata'?'Alasan perubahan':'Penjelasan permintaan'} ${required112}<textarea name="note112" rows="3" maxlength="4000" required placeholder="Jelaskan kebutuhan dan bagian yang perlu ditindaklanjuti.">${E(d.note)}</textarea></label><label>Lampiran / bukti tambahan (opsional)<input type="file" data-ticket-file112="attachment" multiple accept="image/jpeg,image/png,image/webp,application/pdf,text/plain"></label><div>${d.files.map(f=>`<small>▧ ${E(f.name)}</small>`).join('')}</div><p class="sample111">Prototype lokal: pengajuan, pesan, dan hasil tidak dikirim ke distributor. Tidak ada pemotongan kredit.</p><p class="error11" role="alert"></p><footer class="actions107">${d.extension?'':B112('Simpan Draft','save-draft','','text')}<button type="submit" class="btn primary" ${!d.source?'disabled':''}>${d.category==='takedown'?'Ajukan Penurunan':['audio','cover'].includes(d.category)?'Ajukan Penggantian':'Kirim Permintaan'}</button></footer></form>`);const dialog=document.querySelector('#dialog');dialog.classList.add('ticket-dialog112');dialog.querySelectorAll('label>.required105').forEach(star=>{const label=star.parentNode,head=document.createElement('span');label.insertBefore(head,label.firstChild);while(head.nextSibling&&head.nextSibling!==star)head.append(head.nextSibling);head.append(star)});mountMedia105()}
function capture112(){const f=document.querySelector('[data-form112=create]');if(!f||!payload112)return;const fd=new FormData(f),d=payload112;d.note=String(fd.get('note112')||'');d.reason=String(fd.get('reason112')||'');d.checked=!!fd.get('checked112');d.consent=!!fd.get('consent112');d.tracks=fd.getAll('track112');if(!['audio','cid','release-claim','disable-cid','availability'].includes(d.category))d.tracks=d.source?.songs.map(t=>t.id)||[];d.platforms=fd.getAll('platform112');d.condition=fd.get('condition112')||d.condition;d.preview=Number(fd.get('preview112')||0)}
function changedCreator112(){payload112.consent=false;const c=document.querySelector('[name=consent112]');if(c)c.checked=false}
function seedCreators112(){const d=payload112,names=[...new Set(d.source?.songs.filter(t=>d.tracks.includes(t.id)).flatMap(t=>[...(t.metadata.composer||[]),...(t.metadata.lyricist||[])])||[])];d.creators=(names.length?names:['']).map(name=>({name,nik:'',domicile:'',city:'',tracks:d.source.songs.filter(t=>d.tracks.includes(t.id)&&(!name||[...(t.metadata.composer||[]),...(t.metadata.lyricist||[])].includes(name))).map(t=>t.id),ktp:null,signature:null}));}
async function store112(file,kind){if(file.size>40*1024*1024)throw Error('Berkas maksimum 40 MB.');const key='ticket112-'+browserId120();let meta={key,name:file.name,size:file.size,type:file.type};if(kind==='audio'){const info=wav105(await file.arrayBuffer());meta={...meta,valid:true,duration:info.duration,sampleRate:info.rate};}else if(['cover','ktp','signature'].includes(kind)){if(!['image/png','image/jpeg',...(kind==='ktp'?['image/webp']:[])].includes(file.type))throw Error('Gunakan format gambar yang sesuai.');const src=await fileData105(file),img=await imagePending(src);if(kind==='cover'&&(img.naturalWidth!==3000||img.naturalHeight!==3000))throw Error('Cover harus 3000 × 3000 piksel. Artwork tidak diubah otomatis.');const canvas=document.createElement('canvas'),scale=Math.min(1,360/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);meta={...meta,valid:true,width:img.naturalWidth,height:img.naturalHeight,preview:canvas.toDataURL('image/png')};if(kind==='cover')meta.url=meta.preview;if(kind==='ktp'){const previous=documentDraftPending;await prepareDocumentPending(src);const prepared=structuredClone(documentDraftPending);documentDraftPending=previous;delete prepared.original;meta.prepared=prepared;meta.reviewed=false;meta.originalKey=key+'-original';await mediaStore105('readwrite',meta.originalKey,file);meta.preview=prepared.processed;const blob=await (await fetch(prepared.processed)).blob();await mediaStore105('readwrite',key,blob);return meta;}}else if(!['image/jpeg','image/png','image/webp','application/pdf','text/plain'].includes(file.type))throw Error('Lampiran: JPG, PNG, WebP, PDF, atau TXT.');await mediaStore105('readwrite',key,file);return meta;}
function actions112(t){if(!write112())return '<p>Akses hanya baca.</p>';if(isLabel10())return (t.category==='availability'&&t.status!=='done'?B112('Tambahkan dampak laporan','add-impact',t.id,'text'):'')+(t.status==='done'?t.reopenRequest?'<p>Laporan masalah berulang menunggu pemeriksaan petugas.</p>':B112('Laporkan Masalah Masih Ada','report-again',t.id):t.status==='label'?B112('Kirim Kelengkapan','complete',t.id,'primary'):'');if(t.status==='submitted'&&!t.handler)return B112('Ambil Penanganan','claim',t.id,'primary');if(t.handler!==state.user&&ten.role!=='super')return '<p>Penanganan oleh '+E(person112(t.handler))+'.</p>';let html='';if(t.reopenRequest)html=B112('Buka Kembali Kasus','reopen',t.id,'primary')+B112('Tautkan ke Tiket Terkait','link-new',t.id);if(['handling','distributor'].includes(t.status))html+=B112('Catat Hasil','results',t.id,'primary')+B112('Minta Kelengkapan','request',t.id)+B112(t.status==='handling'?'Teruskan ke Distributor':'Catat Tindak Lanjut',t.status==='handling'?'send':'followup',t.id)+(t.items.every(i=>i.status==='confirmed')?B112('Selesaikan Tiket','finish',t.id,'primary'):'');if(t.status!=='done')html+=B112('Eskalasi','escalate',t.id,'text');if(ten.role==='super'){html+=B112('Alihkan Penanganan','assign',t.id,'text');if(t.escalated)html+=B112('Catat Peninjauan','clear-escalation',t.id,'text');}return html}
function file112(f,label='Buka berkas',id=''){return `<div class="file111"><span>▧</span><div><strong>${E(f.name)}</strong><small>${Math.ceil(f.size/1024)} KB</small></div>${B112(label,'file',id)}</div>`}
function requestHtml112(t){const p=t.request;let html=`<p>${E(p.note)}</p>`;if(p.reason)html+=`<p><strong>${E(p.reason)}</strong></p>`;if(t.category==='metadata')html+=diffHtml112(p);if(t.category==='cover')html+=`<div class="cover-pair112"><article><small>Sebelumnya</small>${t.source.cover?.url?`<img src="${E(t.source.cover.url)}" alt="Cover sebelumnya">`:'<p>Berkas sebelumnya belum tersedia.</p>'}</article><article><small>Usulan</small><img src="${E(p.cover.url)}" alt="Usulan cover">${file112(p.cover,'Buka cover asli',t.id+':cover')}</article></div>`;if(t.category==='audio')html+=`<p>${E(t.items[0].label)}</p>${file112(p.audio,'Dengarkan WAV',t.id+':audio')}<audio controls data-blob105="${E(p.audio.key)}"></audio><small>Cuplikan mulai ${p.preview} detik</small>`;if(t.category==='takedown')html+='<p>Seluruh rilisan, termasuk semua lagu. Riwayat dan data katalog tetap disimpan.</p>';if(t.category==='release-claim')html+=t.items.map(i=>`<p><a href="${E(i.url)}" target="_blank" rel="noopener noreferrer">${E(i.url)} ↗</a></p>`).join('');if(t.category==='cid')html+=`<p>${p.creators.length} pencipta · ${t.items.length} lagu</p>${B112('Pratinjau pernyataan','ticket-statement',t.id,'text')}`;if(t.category==='disable-cid')html+='<p>Penonaktifan rekaman ditinjau petugas. Perlakuan klaim sebelumnya perlu konfirmasi distributor.</p>';if(t.category==='availability')html+=`<p>${p.condition==='missing'?'Belum tersedia':'Sebelumnya tersedia, sekarang tidak ditemukan'} · ${E(p.platforms.join(', '))}</p>${B112('Lihat perkembangan distribusi','release',t.release,'text')}`;if(t.category==='availability')html+=(p.urls||[]).filter(Boolean).map(u=>`<p><a href="${E(u)}" target="_blank" rel="noopener noreferrer">${E(u)} ↗</a></p>`).join('')+(t.amendments||[]).map(x=>`<div class="notice111"><strong>Dampak ditambahkan · ${date10(x.at,true)} WIB</strong><p>${E(x.request.note)}</p><p>${x.items.map(i=>E(i.label)).join('<br>')}</p>${x.request.files.map((f,i)=>file112(f,'Buka lampiran',t.id+':amendment:'+t.amendments.indexOf(x)+':'+i)).join('')}</div>`).join('');html+=p.files.map((f,i)=>file112(f,'Buka lampiran',t.id+':attachment:'+i)).join('');return html}
function detail112(id){if(!allowed112())return;const t=ticket112(id);if(!t)return;closeModal();document.querySelector('#ticket-drawer112')?.remove();ui112.open=id;const d=document.createElement('dialog');d.id='ticket-drawer112';d.className='release-drawer106 detail-panel111 ticket-drawer112';const a=Tickets112.attention(ten,t,actor112()),count=t.items.filter(i=>i.status==='confirmed').length;d.innerHTML=`<header class="detail-head111"><div><small>${t.id}</small><h2>${E(names112[t.category])}</h2></div>${B112('×','close-drawer','','icon-close106')}</header><div class="detail-body111"><section class="ticket-hero112">${t.source.cover?.url?`<img src="${E(t.source.cover.url)}" alt="">`:'<span class="ticket-art112">♫</span>'}<div><h2>${E(t.source.title)}</h2><p>${E(t.source.artist)}</p>${tag112(t)}</div></section><dl class="facts11"><div><dt>Label</dt><dd>${E(person112(t.member))}</dd></div><div><dt>Penanggung jawab</dt><dd>${E(person112(t.handler))}</dd></div><div><dt>Diajukan</dt><dd>${date10(t.created,true)} WIB</dd></div><div><dt>Hasil terkonfirmasi</dt><dd>${count} / ${t.items.length} bagian</dd></div><div><dt>UPC</dt><dd>${E(t.source.upc||'Belum tersedia')}</dd></div><div><dt>Tindak lanjut berikutnya</dt><dd>${t.status==='distributor'&&t.nextFollowup?date10(t.nextFollowup,true)+' WIB':'—'}</dd></div></dl>${a?`<p class="notice111">${E(a.text)}</p>`:''}${t.escalated?`<p class="notice111"><strong>Perlu peninjauan</strong><br>${E(t.escalationNote)}</p>`:''}${t.required?`<div class="notice111"><strong>Kelengkapan yang diminta</strong><p>${E(t.required)}</p></div>`:''}${t.reopenRequest?`<div class="notice111"><strong>Masalah dilaporkan kembali</strong><p>${E(t.reopenRequest.note)}</p></div>`:''}<section class="section11"><h3>Langkah berikutnya</h3><div class="actions107">${actions112(t)}</div><p>${t.status==='done'?'Hasil tersimpan; masalah berulang dapat dilaporkan pada tiket ini.':t.status==='label'?'Label melengkapi informasi. Penanggung jawab tetap tercatat.':t.status==='distributor'?'Petugas memantau hasil distributor.':'Petugas memeriksa dan menentukan tindak lanjut.'}</p></section><section class="section11"><h3>Ringkasan permintaan</h3>${requestHtml112(t)}<details><summary>Lagu dan ISRC saat pengajuan</summary>${t.source.songs.map(x=>`<p>${E(x.number+'. '+x.title)} · ${E(x.isrc||'ISRC belum tersedia')}</p>`).join('')}</details></section><section class="section11"><div class="spread"><h3>Hasil per bagian</h3><span>${count} / ${t.items.length}</span></div>${t.items.map(i=>`<article class="result-item112"><strong>${E(i.label)}</strong>${statusBadge111(i.status==='confirmed'?'Terkonfirmasi':i.status==='blocked'?'Ada kendala':'Menunggu hasil',i.status==='confirmed'?'green':i.status==='blocked'?'mustard':'blue')}${i.note?`<p>${E(i.note)}</p><small>${date10(i.at,true)} WIB · ${E(i.reference||'')}</small>`:''}</article>`).join('')}${t.summary?`<div class="notice111"><strong>Ringkasan penyelesaian</strong><p>${E(t.summary)}</p></div>`:''}${t.previousResults?.length?`<details><summary>Hasil sebelum pembukaan kembali (${t.previousResults.length})</summary>${t.previousResults.map(x=>`<article class="result-item112"><p>${E(x.summary)}</p><small>${date10(x.completed,true)} WIB</small>${x.items.map(i=>`<p>${E(i.label)} · ${E(i.note||'')} · ${E(i.reference||'')}</p>`).join('')}</article>`).join('')}</details>`:''}</section><section class="section11"><h3>Percakapan kasus</h3>${t.messages.map((m,i)=>`<article class="message112"><strong>${E(person112(m.actor))}</strong><p>${E(m.note)}</p><small>${date10(m.at,true)} WIB</small>${m.files.map((f,n)=>file112(f,'Buka berkas',t.id+':message:'+i+':'+n)).join('')}</article>`).join('')||'<p>Belum ada pesan tambahan.</p>'}${t.status!=='done'&&write112()?`<form class="form111" data-form112="message" data-id="${t.id}" data-version="${t.version}"><label>Pesan<textarea name="note" rows="2" required maxlength="4000"></textarea></label><label>Lampiran (opsional)<input type="file" name="files" multiple accept="image/jpeg,image/png,application/pdf,text/plain"></label><small>Pesan biasa tidak mengubah status atau penanggung jawab.</small><p class="error11" role="alert"></p><button type="submit" class="btn">Kirim Pesan</button></form>`:''}</section>${!isLabel10()?`<section class="section11"><h3>Catatan internal</h3>${t.internal.map(n=>`<article class="message112"><p>${E(n.note)}</p><small>${E(person112(n.actor))} · ${date10(n.at,true)} WIB</small></article>`).join('')||'<p>Belum ada catatan.</p>'}${write112()&&(t.handler===state.user||ten.role==='super')?B112('Tambah catatan','internal',t.id,'text'):''}</section>`:''}<section class="section11"><h3>Aktivitas terbaru</h3><div class="timeline111">${t.history.filter(h=>!isLabel10()||h.public).slice().reverse().map(h=>`<div class="timeline-row111"><strong>${E(events112[h.action]||h.action)}</strong>${h.note?`<p>${E(h.note)}</p>`:''}<small>${date10(h.at,true)} WIB · ${E(person112(h.actor))}</small></div>`).join('')}</div></section>${t.related?.length?`<section class="section11"><h3>Tiket terkait</h3>${t.related.map(id=>B112(id,'detail',id,'text')).join('')}</section>`:''}<p class="sample111">Simulasi lokal. Hasil dicatat manual untuk mencoba alur, tanpa transaksi atau koneksi distributor.</p></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>{d.remove();if(ui112.open===id)ui112.open=null});mountMedia105();}
function actionForm112(action,id){const t=ticket112(id);if(!t)return;document.querySelector('#ticket-drawer112')?.close();let body='',label=events112[action]||'Catat tindakan';if(action==='claim')body='<p>Ambil tanggung jawab pemeriksaan tiket ini.</p>';else if(action==='assign')body=`<label>Petugas<select name="handler" required>${people.filter(p=>p.super||data.roles.find(r=>r.id===data.assignments[p.id])?.rules.support==='direct').map(p=>`<option value="${p.id}">${E(p.name)}</option>`).join('')}</select></label>`;else if(action==='send')body=`${textField112('reference','Referensi penerusan '+required112,'','required')}<label class="check11"><input name="checked" type="checkbox" required>Permintaan telah diteruskan sesuai cakupan yang ditinjau.</label>${Tickets112.conflicts(Tickets112.init(ten),t).length?`<label class="check11"><input name="aligned" type="checkbox" required>Permintaan terkait (${Tickets112.conflicts(Tickets112.init(ten),t).join(", ")}) telah diselaraskan. Jelaskan keputusan pada catatan tindakan.</label>`:""}<p>Pengingat awal: 3 hari kerja. Ini jadwal tindak lanjut, bukan janji hasil.</p>`;else if(action==='followup')body=`<label>Tindak lanjut berikutnya ${required112}<input name="next" type="datetime-local" value="${new Date(Wami11.addBusinessDays(ten.now,3,calendar11())+7*3600000).toISOString().slice(0,16)}" required></label><p>Usia tiket tetap dihitung sejak pengajuan awal.</p>`;else if(action==='results')body=`<p>Catat hanya hasil yang diperiksa. Bagian terkonfirmasi sebelumnya tetap tersimpan.</p>${t.category==='availability'?'<p class="note107">Hasil laporan ini tidak otomatis mengubah status tayang atau penyelesaian kredit. Konfirmasi distribusi tetap melalui detail Rilisan.</p>':''}${t.items.filter(i=>i.status!=='confirmed').map((i,n)=>`<fieldset class="result-form112" data-result112="${E(i.id)}"><legend>${E(i.label)}</legend><label>Hasil<select name="result-${n}"><option value="skip">Belum dicatat</option><option value="confirmed">Terkonfirmasi berhasil</option><option value="pending">Masih diproses</option><option value="blocked">Ada kendala</option></select></label>${textField112('reference-'+n,'Referensi konfirmasi',i.reference||'')}<label>Penjelasan<textarea name="note-${n}" rows="2">${E(i.note||'')}</textarea></label></fieldset>`).join('')}<label class="check11"><input type="checkbox" name="checked" required>Saya telah memeriksa cakupan dan hasil yang dicatat.</label>`;else if(action==='finish')body='<p>Semua bagian sudah terkonfirmasi. Ringkasan berikut akan terlihat oleh label.</p><label class="check11"><input type="checkbox" name="checked" required>Hasil lengkap dan tidak ada bagian yang masih menunggu.</label>';else if(action==='reopen')body=`<p>${E(t.reopenRequest?.note||'')}</p><p>Riwayat hasil sebelumnya tetap tersedia. Membuka kasus tidak membatalkan perubahan katalog.</p>`;else if(action==='link-new')body=`<label>Tiket terkait<select name="related" required><option value="">Pilih tiket</option>${rows112().filter(x=>x.id!==id&&x.account===t.account).map(x=>`<option value="${x.id}">${x.id} · ${E(x.source.title)}</option>`).join('')}</select></label>`;
if(action!=='claim')body+=`<label>${action==='complete'?'Kelengkapan yang diberikan':action==='report-again'?'Masalah yang masih terjadi':action==='finish'?'Ringkasan hasil':'Keterangan'} ${required112}<textarea name="note" rows="3" required maxlength="4000"></textarea></label>`;if(action==='complete')body+='<label>Berkas kelengkapan (opsional)<input type="file" name="files" multiple accept="image/jpeg,image/png,application/pdf,text/plain"></label>';reviewDialogUI(label,`<form class="form111" data-form112="${action}" data-id="${id}" data-version="${t.version}"><h3>${E(t.source.title)}</h3>${body}<p class="error11" role="alert"></p><footer class="actions107">${B112('Kembali','detail',id,'text')}<button type="submit" class="btn primary">${action==='claim'?'Ambil Penanganan':action==='complete'?'Kirim Kelengkapan':action==='finish'?'Selesaikan Tiket':'Simpan'}</button></footer></form>`)}
function guide112(){return `<section class="panel111"><h2>Standar Tiket Bantuan</h2><p>Draft/revisi diperbaiki di Rilisan. Perubahan setelah pengiriman ditangani melalui tiket. Pengajuan tidak langsung mengganti katalog.</p><table class="table111"><thead><tr><th>Status</th><th>Langkah berikutnya</th></tr></thead><tbody>${Object.entries(states112).map(([id,text])=>`<tr><td>${statusBadge111(text,id==="done"?"green":id==="label"?"mustard":id==="submitted"?"neutral":"blue")}</td><td>${({submitted:'Petugas mengambil penanganan.',handling:'Pemeriksaan, kelengkapan, atau penerusan oleh petugas.',label:'Label mengirim kelengkapan yang diminta.',distributor:'Petugas memantau dan mencatat hasil per bagian.',done:'Hasil lengkap tersimpan; masalah berulang dapat dilaporkan.'})[id]}</td></tr>`).join('')}</tbody></table><p>Pesan biasa dan catatan internal tidak mengubah status. Tindak lanjut jatuh tempo mengikuti pengingat, bukan jaminan penyelesaian. Tidak ada selesai massal atau penutupan otomatis karena label belum merespons.</p><p class="sample111">Baseline tindak lanjut distributor: 3 hari kerja. Ketentuan Content ID, penurunan parsial, biaya/benefit, target respons dan eskalasi masih menunggu verifikasi staf. Tidak ada pemotongan kredit pada prototype.</p></section>`}
async function statement112(t=null){if(!t)capture112();const p=t?.request||payload112;if(!p)return;if(!t&&p.category==='cid'&&!p.creators.length)seedCreators112();document.querySelector('#ticket-drawer112')?.close();reviewDialogUI('Pratinjau pernyataan',`<div class="statement112"><p class="sample111">Pratinjau data surat dari formulir repo. Format final dan persyaratan masih perlu verifikasi staf.</p><h2>${E(p.source.title)}</h2><p>Label: ${E(person112(t?.member||p.source.member))}</p>${p.creators.map((c,i)=>`<section><h3>Pencipta ${i+1} · ${E(c.name)}</h3><p>NIK ${E(c.nik||'belum diisi')}<br>${E(c.domicile)}<br>Kota penandatanganan: ${E(c.city)}</p><p>Lagu: ${p.source.songs.filter(x=>c.tracks.includes(x.id)).map(x=>E(x.title)+' · '+E(x.isrc||'ISRC belum tersedia')).join('<br>')}</p>${c.signature?.preview?`<img class="signature112" src="${E(c.signature.preview)}" alt="Tanda tangan pencipta">`:'<p>Tanda tangan belum tersedia.</p>'}${c.ktp?B112('Buka KTP pencipta','file',t?t.id+':creator:'+i+':ktp':'draft:creator:'+i+':ktp','text'):''}</section>`).join('')}<p>Data dan dokumen digunakan untuk pemeriksaan pengajuan Content ID sesuai persetujuan pencipta.</p>${t?B112('Kembali ke tiket','detail',t.id,'primary'):B112('Kembali ke formulir','form-back','','primary')}</div>`)}
async function openFile112(id){const parts=id.split(':'),t=parts[0]==='draft'?null:ticket112(parts[0]);if(parts[0]!=='draft'&&!t)return;const p=t?.request||payload112;let file;if(parts[1]==='creator'){file=p.creators[+parts[2]]?.[parts[3]];}else if(parts[1]==='attachment')file=p.files[+parts[2]];else if(parts[1]==='amendment')file=t.amendments[+parts[2]]?.request.files[+parts[3]];else if(parts[1]==='message')file=t.messages[+parts[2]]?.files[+parts[3]];else file=p[parts[1]];if(!file)throw Error('Berkas tidak tersedia.');const blob=await mediaStore105('readonly',file.key);if(!blob)throw Error('Berkas belum tersedia pada browser ini.');document.querySelector('#ticket-drawer112')?.close();const url=URL.createObjectURL(blob);reviewDialogUI(file.name,`<div class="file-preview112">${file.type?.startsWith('image/')?`<img src="${url}" alt="Pratinjau berkas">`:file.type?.includes('audio')?`<audio controls src="${url}"></audio>`:file.type==='application/pdf'?`<iframe title="Pratinjau PDF" src="${url}"></iframe>`:`<p>${E(await blob.text())}</p>`}<a class="btn" href="${url}" download="${E(file.name)}">Unduh berkas</a>${t?B112('Kembali ke tiket','detail',t.id,'text'):B112('Kembali ke formulir','form-back','','text')}</div>`);setTimeout(()=>URL.revokeObjectURL(url),600000)}
async function editKtp112(i){const c=payload112.creators[i];if(!c?.ktp)return;capture112();docEditor112={index:i,d:structuredClone(c.ktp.prepared)};reviewDialogUI('Tinjau KTP pencipta',`<div class="document-workbench"><img id="ktp-preview112" src="${E(docEditor112.d.processed)}" alt="KTP disiapkan untuk pemeriksaan"><p>Periksa arah tulisan dan seluruh sisi kartu. Berkas asli tetap disimpan.</p><div class="actions107">${B112('Putar 90°','ktp-rotate')}${B112('Gunakan seluruh gambar','ktp-reset')}</div><label class="check11"><input type="checkbox" id="ktp-confirm112">Seluruh data dan sisi kartu terlihat jelas.</label>${B112('Gunakan dokumen','ktp-save','','primary')}</div>`)}
async function redrawKtp112(){const old=documentDraftPending;documentDraftPending=docEditor112.d;await drawDocumentPending();documentDraftPending=old;document.querySelector('#ktp-preview112').src=docEditor112.d.processed;document.querySelector('#ktp-confirm112').checked=false;}
