window.addEventListener('submit',async e=>{const f=e.target.closest('[data-form112]');if(!f)return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const b=f.querySelector('button[type=submit]');if(b.disabled)return;b.disabled=true;try{const action=f.dataset.form112;if(action==='create'){capture112();if(payload112.category==='cid'&&payload112.creators.some(c=>!c.ktp?.reviewed))throw Error('Tinjau dan konfirmasikan KTP setiap pencipta sebelum mengajukan.');const p=structuredClone(payload112);for(const c of p.creators){if(c.ktp)delete c.ktp.prepared;}const id=run112(p.extension?'extend':'create',p.extension?{...p,id:p.extension}:p);payload112=null;closeModal();route112();detail112(id);toast('Permintaan terkirim. Tim akan memeriksa dan menindaklanjuti.');return;}const fd=new FormData(f),v=Object.fromEntries(fd),p={id:f.dataset.id,version:+f.dataset.version,note:v.note||'',reference:v.reference||'',handler:v.handler,checked:!!v.checked,aligned:!!v.aligned,related:v.related};if(v.next)p.next=Date.parse(v.next+':00+07:00');if(action==='results')p.results=[...f.querySelectorAll('[data-result112]')].map((el,n)=>({id:el.dataset.result112,status:v['result-'+n],note:v['note-'+n],reference:v['reference-'+n]})).filter(r=>r.status!=='skip');p.files=[];const files=fd.getAll('files').filter(f=>f?.size);if(files.length>5)throw Error('Maksimum 5 berkas.');for(const file of files)p.files.push(await store112(file,'attachment'));const id=run112(action,p);closeModal();render();detail112(id);toast('Tiket diperbarui.')}catch(err){f.querySelector('.error11').textContent=err.message;}finally{if(b.isConnected)b.disabled=false}},true);


